    if ($PSBoundParameters.ContainsKey('ComputedadcCookieAttribute')) { $properties['computedadccookieattribute'] = $ComputedadcCookieAttribute }
    if ($PSBoundParameters.ContainsKey('CookiePassphrase')) { $properties['cookiepassphrase'] = $CookiePassphrase }
    if ($PSBoundParameters.ContainsKey('DBSLB')) { $properties['dbslb'] = $DBSLB }
    if ($PSBoundParameters.ContainsKey('HTTPOnlyCookieFlag')) { $properties['httponlycookieflag'] = $HTTPOnlyCookieFlag }
    if ($PSBoundParameters.ContainsKey('LbHashAlgorithm')) { $properties['lbhashalgorithm'] = $LbHashAlgorithm }
    if ($PSBoundParameters.ContainsKey('LbHashFingers')) { $properties['lbhashfingers'] = $LbHashFingers }
    if ($PSBoundParameters.ContainsKey('LBProfileName')) { $properties['lbprofilename'] = $LBProfileName }
    if ($PSBoundParameters.ContainsKey('LiteraladcCookieAttribute')) { $properties['literaladccookieattribute'] = $LiteraladcCookieAttribute }
    if ($PSBoundParameters.ContainsKey('ProcessLocal')) { $properties['processlocal'] = $ProcessLocal }
    if ($PSBoundParameters.ContainsKey('Proximityfromself')) { $properties['proximityfromself'] = $Proximityfromself }
    if ($PSBoundParameters.ContainsKey('StoremqttClientIdandUserName')) { $properties['storemqttclientidandusername'] = $StoremqttClientIdandUserName }
    if ($PSBoundParameters.ContainsKey('UseencryptedPersistenceCookie')) { $properties['useencryptedpersistencecookie'] = $UseencryptedPersistenceCookie }
    if ($PSBoundParameters.ContainsKey('UsesecuredPersistenceCookie')) { $properties['usesecuredpersistencecookie'] = $UsesecuredPersistenceCookie }

    $body = [System.Collections.Generic.Dictionary[string, object]]::new([System.StringComparer]::Ordinal)
    foreach ($key in $properties.Keys) {
