        }
    }

    if ($PSCmdlet.ShouldProcess("$LBProfileName", 'Create lbprofile')) {
        $response = Invoke-NSRestRequest @transportParameters -Session $Session -Method POST -Task config -Type lbprofile -Payload @{ lbprofile = $body } -RawResponse

