        [switch] $CookiePassphrase,

        [Parameter()]
        [ValidateSet('ENABLED', 'DISABLED')]
        [switch] $DBSLB,

        [Parameter()]
        [ValidateSet('ENABLED', 'DISABLED')]
        [switch] $HTTPOnlyCookieFlag,

        [Parameter()]
        [ValidateSet('DEFAULT', 'PRAC', 'JARH')]
        [switch] $LbHashAlgorithm,

        [Parameter()]
        [switch] $LbHashFingers,

        [Parameter()]
        [switch] $LiteraladcCookieAttribute,

        [Parameter()]
        [ValidateSet('ENABLED', 'DISABLED')]
        [switch] $ProcessLocal,

        [Parameter()]
        [ValidateSet('YES', 'NO')]
        [switch] $Proximityfromself,

        [Parameter()]
        [ValidateSet('YES', 'NO')]
        [switch] $StoremqttClientIdandUserName,

        [Parameter()]
        [ValidateSet('ENABLED', 'DISABLED')]
        [switch] $UseencryptedPersistenceCookie,

        [Parameter()]
        [ValidateSet('ENABLED', 'DISABLED')]
        [switch] $UsesecuredPersistenceCookie,

        [Parameter()]
        [psobject] $Session = (Get-NSSession),

        [Parameter()]
        [switch] $IgnoreNotFound,

