        $transportParameters = @{}
        if ($PSBoundParameters.ContainsKey('IgnoreNotFound')) { $transportParameters.IgnoreNotFound = $IgnoreNotFound }
        if ($PSBoundParameters.ContainsKey('ReturnNullOnNotFound')) { $transportParameters.ReturnNullOnNotFound = $ReturnNullOnNotFound }
        if ($PSBoundParameters.ContainsKey('ThrowOnWarning')) { $transportParameters.ThrowOnWarning = $ThrowOnWarning }

        $body = @{ lbprofilename = $LBProfileName }
        if ($PSBoundParameters.ContainsKey('ComputedadcCookieAttribute')) { $body['computedadccookieattribute'] = $true }
        if ($PSBoundParameters.ContainsKey('CookiePassphrase')) { $body['cookiepassphrase'] = $true }
        if ($PSBoundParameters.ContainsKey('DBSLB')) { $body['dbslb'] = $true }
        if ($PSBoundParameters.ContainsKey('HTTPOnlyCookieFlag')) { $body['httponlycookieflag'] = $true }
        if ($PSBoundParameters.ContainsKey('LbHashAlgorithm')) { $body['lbhashalgorithm'] = $true }
        if ($PSBoundParameters.ContainsKey('LbHashFingers')) { $body['lbhashfingers'] = $true }
        if ($PSBoundParameters.ContainsKey('LiteraladcCookieAttribute')) { $body['literaladccookieattribute'] = $true }
        if ($PSBoundParameters.ContainsKey('ProcessLocal')) { $body['processlocal'] = $true }
        if ($PSBoundParameters.ContainsKey('Proximityfromself')) { $body['proximityfromself'] = $true }
        if ($PSBoundParameters.ContainsKey('StoremqttClientIdandUserName')) { $body['storemqttclientidandusername'] = $true }
        if ($PSBoundParameters.ContainsKey('UseencryptedPersistenceCookie')) { $body['useencryptedpersistencecookie'] = $true }
        if ($PSBoundParameters.ContainsKey('UsesecuredPersistenceCookie')) { $body['usesecuredpersistencecookie'] = $true }

        if ($body.Count -le 1) {
            throw 'Specify at least one property switch to clear.'
        }

        if ($PSCmdlet.ShouldProcess("$LBProfileName", 'Clear lbprofile properties')) {
            $response = Invoke-NSRestRequest @transportParameters -Session $Session -Method POST -Task config -Type lbprofile -Action unset -Payload @{ lbprofile = $body } -RawResponse

            if ($PassThru) {
